// Generated by secure-by-design v0.1.0 for DPDP §6 (Consent).
// Reads from ../../privacy-security-manifest.yaml.
// Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
// Docs: docs/scaffolds/consent.md
//
// Reference: India DPDP Act 2023, §5 (Notice), §6 (Consent), §7 (Legitimate use).
// This file scaffolds the *recording*, *verification*, and *withdrawal* of consent.
// It is not a substitute for legal review of your consent flow or notice text.

import { createHash } from 'node:crypto';

export type ConsentBasis = 'explicit' | 'contract' | 'public-interest' | 'medical-emergency' | 'employment';

export type ConsentPurpose = string; // e.g. 'patient.diagnosis.ai-suggestion'

export interface ConsentRecord {
  dataPrincipalId: string;          // the user / patient ID
  purpose: ConsentPurpose;          // specific purpose; do not collapse multiple purposes into one
  category: string;                 // matches dataCategories[].name in manifest
  basis: ConsentBasis;
  noticeVersion: string;            // version hash of the notice text shown
  consentTextHash: string;          // SHA-256 of the exact consent text
  language: string;                 // ISO 639-1 (e.g. 'en', 'hi', 'ta')
  givenAt: Date;
  givenByActor: 'self' | 'parent-guardian'; // parent-guardian → see children_gate.ts
  channel: 'web' | 'mobile' | 'in-person' | 'api';
  withdrawnAt: Date | null;
  expiresAt: Date | null;           // optional — drives re-prompt
}

export interface ConsentStore {
  insert(record: ConsentRecord): Promise<string>; // returns consent ID
  findActive(dataPrincipalId: string, purpose: ConsentPurpose): Promise<ConsentRecord | null>;
  withdraw(consentId: string, when: Date): Promise<void>;
  listFor(dataPrincipalId: string): Promise<ConsentRecord[]>;
}

// Inject a concrete ConsentStore (Prisma, Drizzle, etc.) at app boot.
let store: ConsentStore | null = null;
export function setConsentStore(s: ConsentStore): void {
  store = s;
}

function requireStore(): ConsentStore {
  if (!store) {
    throw new Error('secure-by-design: ConsentStore not configured. Call setConsentStore() at app boot.');
  }
  return store;
}

export function hashConsentText(text: string): string {
  return createHash('sha256').update(text, 'utf8').digest('hex');
}

/**
 * Record a consent event. Call when the data principal clicks "I agree" on a notice.
 *
 * DPDP §6 requirements this satisfies:
 *  - Free, specific, informed, unconditional, unambiguous
 *  - Recorded with purpose
 *  - Recorded with the notice text actually shown (via consentTextHash)
 *  - Withdrawable (withdraw() below)
 *
 * NOT satisfied by this function alone — you must also:
 *  - Present the notice in a clear language (§5(3))
 *  - Make withdrawal as easy as giving consent (§6(4))
 *  - Refrain from making consent a precondition for service provision unless the
 *    service legitimately requires the data (§6(2))
 */
export async function recordConsent(input: Omit<ConsentRecord, 'givenAt' | 'withdrawnAt'> & { givenAt?: Date }): Promise<string> {
  const record: ConsentRecord = {
    ...input,
    givenAt: input.givenAt ?? new Date(),
    withdrawnAt: null,
  };
  return requireStore().insert(record);
}

/**
 * Check whether the data principal has active consent for a specific purpose.
 * Use this gate BEFORE any code path that processes personal data for that purpose.
 *
 * Returns null if no active consent exists. Caller must refuse the operation
 * or fall back to a legitimate-use basis under §7 (if applicable).
 */
export async function verifyConsent(
  dataPrincipalId: string,
  purpose: ConsentPurpose,
): Promise<ConsentRecord | null> {
  const record = await requireStore().findActive(dataPrincipalId, purpose);
  if (!record) return null;
  if (record.withdrawnAt) return null;
  if (record.expiresAt && record.expiresAt < new Date()) return null;
  return record;
}

/**
 * Withdraw consent. After this, any subsequent verifyConsent() returns null.
 * Per §6(5), withdrawal must not affect lawfulness of processing done before withdrawal.
 */
export async function withdrawConsent(consentId: string): Promise<void> {
  await requireStore().withdraw(consentId, new Date());
}

/**
 * Surface a data principal's full consent history. Used by the DSR access endpoint.
 */
export async function listConsents(dataPrincipalId: string): Promise<ConsentRecord[]> {
  return requireStore().listFor(dataPrincipalId);
}

/**
 * Convenience guard for Express handlers. Throws if no active consent.
 * Wrap your handler body when consent is required.
 */
export async function requireConsent(
  dataPrincipalId: string,
  purpose: ConsentPurpose,
): Promise<ConsentRecord> {
  const record = await verifyConsent(dataPrincipalId, purpose);
  if (!record) {
    const err: Error & { statusCode?: number; code?: string } = new Error(
      `No active consent for purpose=${purpose}. DPDP §6.`,
    );
    err.statusCode = 451; // Unavailable For Legal Reasons
    err.code = 'CONSENT_REQUIRED';
    throw err;
  }
  return record;
}
